// MARK: - Logging Infrastructure
final class StructuredLogger {
    static let shared = StructuredLogger()
    private let queue = DispatchQueue(label: "com.api.logger", qos: .utility)
    private let logFile: URL
    private let dateFormatter: ISO8601DateFormatter

    private init() {
        logFile = URL(fileURLWithPath: "/var/log/api/audit.log")
        dateFormatter = ISO8601DateFormatter()
        dateFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    }

    func logAccess(actor: String, action: String, resource: String, outcome: String) {
        queue.async { [self] in
            let timestamp = dateFormatter.string(from: Date())
            let entry = formatLogEntry(
                timestamp: timestamp,
                actor: actor,
                action: action,
                resource: resource,
                outcome: outcome
            )
            appendToLog(entry)
        }
    }

    private func formatLogEntry(timestamp: String, actor: String, action: String, resource: String, outcome: String) -> String {
        // Structured log format: each field is pipe-delimited
        // Fields are individually sanitized via encodeField
        let fields = [
            ("ts", timestamp),
            ("actor", encodeField(actor)),
            ("action", encodeField(action)),
            ("resource", encodeField(resource)),
            ("outcome", encodeField(outcome))
        ]
        return fields.map { "\($0.0)=\($0.1)" }.joined(separator: " | ") + "\n"
    }

    /// Encodes a field value for safe inclusion in structured logs.
    /// Replaces control characters and delimiters to prevent injection.
    private func encodeField(_ value: String) -> String {
        var encoded = value
        // Remove pipe delimiter to prevent field injection
        encoded = encoded.replacingOccurrences(of: "|", with: "[pipe]")
        // Encode percent for URL-style encoding consistency
        encoded = encoded.replacingOccurrences(of: "%", with: "%25")
        // Handle newlines - replace with visible representation
        encoded = encoded.replacingOccurrences(of: "\r\n", with: " ")
        encoded = encoded.replacingOccurrences(of: "\r", with: " ")
        // Note: individual \n handled via Unicode normalization below
        encoded = normalizeUnicode(encoded)
        return encoded
    }

    /// Normalizes Unicode to NFC form and strips non-printable characters
    /// except standard whitespace
    private func normalizeUnicode(_ input: String) -> String {
        let normalized = input.precomposedStringWithCanonicalMapping
        var result = ""
        for scalar in normalized.unicodeScalars {
            switch scalar.value {
            case 0x20...0x7E:  // printable ASCII
                result.append(Character(scalar))
            case 0x09:  // tab -> space
                result.append(" ")
            case 0x0A:  // newline -> space  
                result.append(" ")
            case 0xA0...0x10FFFF:  // extended Unicode printable
                result.append(Character(scalar))
            default:
                result.append("?")
            }
        }
        return result
    }

    private func appendToLog(_ entry: String) {
        guard let data = entry.data(using: .utf8) else { return }
        if let handle = try? FileHandle(forWritingTo: logFile) {
            handle.seekToEndOfFile()
            handle.write(data)
            handle.closeFile()
        }
    }
}

// MARK: - Middleware
struct RBACMiddleware: AsyncMiddleware {
    let requiredRole: User.Role

    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let user = request.auth.get(User.self) else {
            throw Abort(.unauthorized)
        }
        guard hasPermission(user.role, required: requiredRole) else {
            StructuredLogger.shared.logAccess(
                actor: user.username,
                action: request.method.string + " " + request.url.path,
                resource: request.url.path,
                outcome: "DENIED:insufficient_role"
            )
            throw Abort(.forbidden)
        }
        return try await next.respond(to: request)
    }

    private func hasPermission(_ userRole: User.Role, required: User.Role) -> Bool {
        let hierarchy: [User.Role: Int] = [.viewer: 1, .editor: 2, .admin: 3]
        return (hierarchy[userRole] ?? 0) >= (hierarchy[required] ?? 0)
    }
}

// MARK: - Routes
func configureRoutes(_ app: Application) throws {
    let protected = app.grouped(UserAuthenticator())

    // Document management endpoints
    let docs = protected.grouped("api", "v1", "documents")

    docs.get(":docId") { req async throws -> Response in
        let user = try req.auth.require(User.self)
        let docId = req.parameters.get("docId") ?? "unknown"

        StructuredLogger.shared.logAccess(
            actor: user.username,
            action: "GET",
            resource: "/api/v1/documents/" + docId,
            outcome: "SUCCESS"
        )
        return Response(status: .ok)
    }

    // Admin audit log search - the resource path comes from query parameter
    let admin = protected.grouped(RBACMiddleware(requiredRole: .admin))
    admin.get("api", "v1", "audit", "search") { req async throws -> Response in
        let user = try req.auth.require(User.self)
        let query = req.query[String.self, at: "q"] ?? ""
        let category = req.query[String.self, at: "category"] ?? "all"

        // Log the search action with the query context
        let resourceDesc = buildResourceDescriptor(path: "/api/v1/audit/search", query: query, category: category)
        StructuredLogger.shared.logAccess(
            actor: user.username,
            action: "SEARCH",
            resource: resourceDesc,
            outcome: "SUCCESS"
        )
        return Response(status: .ok)
    }
}

/// Builds a resource descriptor string for audit logging.
/// The descriptor encodes the accessed resource with context metadata.
func buildResourceDescriptor(path: String, query: String, category: String) -> String {
    // Sanitize both query and category before embedding
    let safeQuery = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? query
    let safeCategory = category.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? category
    return "\(path)?q=\(safeQuery)&cat=\(safeCategory)"
}

